import{_ as s,o as n,a as p,b as t}from"./app.DKoEZOcr.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"辅助数据类型","link":"/api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/aux_data_types"},{"text":"RoundMode","link":"/api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RoundMode"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RoundMode.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RoundMode.md","lastUpdated":1786950127000}'),e={name:"api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RoundMode.md"};function c(_,a,l,r,o,d){return n(),p("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>RoundMode<span id="ZH-CN_TOPIC_0000001956862301"></span></h1><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">RoundMode</td><td align="left">用于设置控制舍入模式。<br>enum class RoundMode { <br> CAST_NONE = 0, <br> CAST_RINT, <br> CAST_FLOOR,<br> CAST_CEIL,<br> CAST_ROUND,<br> CAST_TRUNC,<br> CAST_ODD,<br> CAST_HYBRID <br>};<br>•  CAST_NONE：当转换过程存在精度损失时，按 CAST_RINT 模式处理；当不存在精度损失时，不进行舍入。<br>•  CAST_RINT：向最近的偶数舍入。<br>    -  若待舍入部分的首位为 0，则不进位。<br>    -  若待舍入部分的首位为 1 且后续位不全为 0，则进位。<br>    -  若待舍入部分的首位为 1 且后续位全为 0：当非舍入部分的末位为 0，则不进位。当非舍入部分的末位为 1，则进位。<br>•  CAST_FLOOR：向负无穷大方向舍入。<br>    -  若符号位（S）为 0（正数），不进位。<br>    -  若符号位（S）为 1（负数）：当待舍入部分全为 0，则不进位。否则，进位。<br>•  CAST_CEIL：向正无穷大方向舍入。<br>    -  若符号位（S）为 1（负数），不进位。<br>    -  若符号位（S）为 0（正数）：当待舍入部分全为 0，则不进位。否则，进位。<br>•  CAST_ROUND： 四舍五入。若待舍入部分的首位为0，则不进位。否则，进位。<br>•  CAST_TRUNC： 直接丢弃待舍入部分。<br>•  CAST_ODD：向最近的奇数舍入。<br>    -  若待舍入部分全为 0，则不进位。<br>    -  若待舍入部分不全为 0：非舍入部分的末位为 1，则不进位。当非舍入部分的末位为 0，则进位。<br>•  CAST_HYBRID：随机舍入，目前特指输出结果是hifloat8_t数据类型时的随机舍入。</td></tr></tbody></table><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">enum</span><span class="w"> </span><span class="k">class</span><span class="w"> </span><span class="nc">RoundMode</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">CAST_NONE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">CAST_RINT</span><span class="p">,</span>
<span class="w">    </span><span class="n">CAST_FLOOR</span><span class="p">,</span>
<span class="w">    </span><span class="n">CAST_CEIL</span><span class="p">,</span>
<span class="w">    </span><span class="n">CAST_ROUND</span><span class="p">,</span>
<span class="w">    </span><span class="n">CAST_TRUNC</span><span class="p">,</span>
<span class="w">    </span><span class="n">CAST_ODD</span><span class="p">,</span>
<span class="w">    </span><span class="n">CAST_HYBRID</span>
<span class="p">};</span>
</code></pre></div></article></div>`,1)])])}const A=s(e,[["render",c]]);export{b as __pageData,A as default};
